// lib/cv/font.ts
//
// Geist Regular (SIL Open Font License 1.1 — the font Next itself ships with,
// at node_modules/next/dist/compiled/@vercel/og/Geist-Regular.ttf), embedded as
// a base64 data URI so the CV PDF carries the font in its own bytes and prints
// identically at any shop, with no font file to trace or fetch at runtime.
// react-pdf decodes a data: URI via fontkit (see @react-pdf/font).
//
// Regenerate: base64-encode the TTF into this constant. Bold/emphasis in the
// templates is size + colour + spacing, not a second weight, so one face is
// enough and the CV never depends on a font the printer might not have.

export const GEIST_REGULAR_DATA_URI =
  'data:font/ttf;base64,'


// Geist Bold (same OFL family, from the vercel/geist-font distribution), for a
// genuinely bold name in the CV PDF — react-pdf has no faux-bold, so a bold
// weight needs its own registered face.
export const GEIST_BOLD_DATA_URI = 'data:font/ttf;base64,'
